/* Reset & base */
* {
  margin: 0;
  padding: 0;
  box-sizing: border-box;
}

body {
  font-family: 'Segoe UI', Arial, Helvetica, sans-serif;
  line-height: 1.6;
  color: #333;
  background-color: #faf8f5;
}

/* Hero */
.hero {
  background: linear-gradient(135deg, #e8d5b7 0%, #d4c5a9 100%);
  padding: 6rem 2rem;
  text-align: center;
  color: #4a3728;
}

.hero-title {
  font-size: 3rem;
  margin-bottom: 0.5rem;
  color: #5a3e2b;
  text-shadow: 1px 1px 2px rgba(0,0,0,0.1);
}

.hero-tagline {
  font-size: 1.4rem;
  margin-bottom: 1rem;
  color: #6b5c4a;
}

.hero-subtitle {
  font-size: 1.1rem;
  max-width: 600px;
  margin: 0 auto;
  color: #555;
}

/* Menu */
.menu-section {
  padding: 3rem 2rem;
  background-color: #fff;
}

.menu-section h2 {
  text-align: center;
  font-size: 1.8rem;
  margin-bottom: 1.5rem;
  color: #5a3e2b;
}

.menu-grid {
  display: grid;
  grid-template-columns: repeat(auto-fit, minmax(200px, 1fr));
  gap: 1.5rem;
  max-width: 700px;
  margin: 0 auto;
}

.menu-item {
  text-align: center;
  padding: 1.5rem 1rem;
  background: #fdfbf7;
  border-radius: 8px;
  box-shadow: 0 2px 6px rgba(0,0,0,0.06);
}

.item-name {
  display: block;
  font-weight: 600;
  margin-bottom: 0.3rem;
  color: #4a3728;
}

.item-price {
  font-size: 1.2rem;
  color: #8b6914;
  font-weight: 700;
}

/* Hours */
.hours-section {
  padding: 3rem 2rem;
  background-color: #f0e9dd;
  text-align: center;
}

.hours-section h2 {
  margin-bottom: 1rem;
  color: #5a3e2b;
}

.hours-list {
  list-style: none;
  max-width: 500px;
  margin: 0 auto;
  text-align: left;
}

.hours-list li {
  padding: 0.6rem 0;
  border-bottom: 1px solid #d9c8b0;
}

.hours-list li:last-child {
  border-bottom: none;
}

.hours-list strong {
  color: #5a3e2b;
}

/* Contact */
.contact-section {
  padding: 3rem 2rem;
  background-color: #fff;
}

.contact-note {
  text-align: center;
  margin-bottom: 1.5rem;
  color: #6b5c4a;
}

.contact-form {
  max-width: 500px;
  margin: 0 auto;
  display: flex;
  flex-direction: column;
  gap: 1rem;
}

.form-group {
  display: flex;
  flex-direction: column;
  gap: 0.3rem;
}

.form-group label {
  font-weight: 600;
  color: #4a3728;
}

.form-group input,
.form-group textarea {
  padding: 0.7rem;
  border: 1px solid #ccc;
  border-radius: 6px;
  font-size: 1rem;
  font-family: inherit;
  transition: border-color 0.2s;
}

.form-group input:focus,
.form-group textarea:focus {
  outline: none;
  border-color: #8b6914;
}

.contact-form button {
  padding: 0.8rem;
  background-color: #5a3e2b;
  color: #fff;
  border: none;
  border-radius: 6px;
  font-size: 1rem;
  cursor: pointer;
  transition: background-color 0.2s;
}

.contact-form button:hover {
  background-color: #4a3728;
}

/* Thank you message */
.thank-you-message {
  text-align: center;
  margin-top: 1rem;
  font-size: 1.1rem;
  color: #2e7d32;
  font-weight: 600;
}

.hidden {
  display: none;
}

/* Footer */
.footer {
  padding: 1.5rem 2rem;
  text-align: center;
  background-color: #5a3e2b;
  color: #faf8f5;
  font-size: 0.9rem;
}

/* Responsive */
@media (max-width: 600px) {
  .hero-title {
    font-size: 2rem;
  }

  .hero-subtitle {
    font-size: 0.95rem;
  }

  .menu-grid {
    grid-template-columns: 1fr;
  }

  .hours-section,
  .contact-section {
    padding: 2rem 1rem;
  }
}

// Form submission handler - shows thank-you message without reloading
const form = document.getElementById('contact-form');
const thankYou = document.getElementById('thank-you');

form.addEventListener('submit', function(e) {
  e.preventDefault();

  // Simple validation (HTML5 already handles required fields)
  const name = document.getElementById('name').value.trim();
  const email = document.getElementById('email').value.trim();
  const message = document.getElementById('message').value.trim();

  if (!name || !email || !message) {
    alert('Veuillez remplir tous les champs.');
    return;
  }

  // Show thank-you message
  thankYou.classList.remove('hidden');
  form.reset();

  // Optional: scroll to top after submission
  window.scrollTo({ top: 0, behavior: 'smooth' });
});

